// Minimal mock of @minecraft/server sufficient to execute the addon's logic.
export const KNOWN_BLOCKS = new Set();
export const commandLog = [];
export const failedCommands = [];

export class BlockPermutation {
  static resolve(id) {
    if (!KNOWN_BLOCKS.has(id)) throw new Error(`unknown block ${id}`);
    return { __id: id };
  }
}

class Dimension {
  constructor(id) { this.id = id; }
  runCommand(cmd) {
    commandLog.push(cmd);
    return { successCount: 1 };
  }
  getBlock(loc) { return { location: loc, typeId: "minecraft:air", setPermutation() {} }; }
}

const overworld = new Dimension("minecraft:overworld");

class EventSignal {
  constructor(name) { this.name = name; this.handlers = []; }
  subscribe(fn) { this.handlers.push(fn); return fn; }
  unsubscribe(fn) { this.handlers = this.handlers.filter((h) => h !== fn); }
  emit(ev) { for (const h of [...this.handlers]) h(ev); }
}

const dynamicProps = new Map();

export const world = {
  afterEvents: {
    itemUse: new EventSignal("itemUse"),
    itemUseOn: new EventSignal("itemUseOn"),
    buttonPush: new EventSignal("buttonPush"),
    playerSpawn: new EventSignal("playerSpawn"),
  },
  beforeEvents: {
    playerInteractWithBlock: new EventSignal("playerInteractWithBlock"),
  },
  getDimension: () => overworld,
  getAllPlayers: () => players,
  setDynamicProperty: (k, v) => dynamicProps.set(k, v),
  getDynamicProperty: (k) => dynamicProps.get(k),
  getTimeOfDay: () => 6000,
  getAbsoluteTime: () => 6000,
  sendMessage: () => {},
};

export const players = [];

export const systemAfterEvents = { scriptEventReceive: new EventSignal("scriptEventReceive") };

export const scheduled = { intervals: new Map(), timeouts: [], nextId: 1 };
export const system = {
  afterEvents: systemAfterEvents,
  currentTick: 0,
  run(fn) { scheduled.timeouts.push(fn); return scheduled.nextId++; },
  runTimeout(fn) { scheduled.timeouts.push(fn); return scheduled.nextId++; },
  runInterval(fn, period) {
    const id = scheduled.nextId++;
    scheduled.intervals.set(id, { fn, period });
    return id;
  },
  clearRun(id) { scheduled.intervals.delete(id); },
};

/** Advance the fake scheduler. */
export function pump(ticks) {
  for (let t = 0; t < ticks; t++) {
    system.currentTick++;
    const due = scheduled.timeouts.splice(0, scheduled.timeouts.length);
    for (const fn of due) fn();
    for (const [, entry] of [...scheduled.intervals]) entry.fn();
  }
}

export const ItemStack = class { constructor(id, amount = 1) { this.typeId = id; this.amount = amount; } };
export const EquipmentSlot = { Mainhand: "Mainhand" };
export const overworldDimension = overworld;
